def UNCONVERT(text, name):
    """Map live text back to its pre-round-36 form, for historical replays.

    Rounds 30-35 pin their own ledger's post-edit text against the live appendix
    and related_work. Round 36 rewrote that prose, so those pins are asserted
    against the un-converted text rather than restated -- the historical
    assertion is preserved exactly, and round 36 is the documented reason.
    """
    for _o, _n in R36_BY_FILE.get(name, []):
        text = text.replace(_n, _o)
    return text


# ---- \textbf machinery, shared by 13h and 13i ----------------------------------
def spans(text):
    """(start, end, inner_start, inner_end) per \\textbf{...}, brace-matched."""
    out = []
    for m in re.finditer(r"\\textbf\{", text):
        i, depth = m.end(), 1
        while i < len(text) and depth:
            if text[i] == "\\":
                i += 2
                continue
            if text[i] == "{":
                depth += 1
            elif text[i] == "}":
                depth -= 1
                if not depth:
                    break
            i += 1
        if depth:
            return None            # unbalanced: caller turns this into a failure
        out.append((m.start(), i + 1, m.end(), i))
    return out


def unbold(text):
    while True:
        s = spans(text)
        if s is None:
            raise ValueError("unbalanced \\textbf")
        if not s:
            return text
        a, b, ia, ib = s[0]
        text = text[:a] + text[ia:ib] + text[b:]


def de_float(text):
    return re.sub(r"\\begin\{(figure|table)\}.*?\\end\{\1\}", " ", text, flags=re.S)


def words(text):
    return collections.Counter(unbold(text).split())


