    ck("\\label{fig:ladder}" in meth,
       "the ladder figure is not in methodology.tex")
    ck("\\label{fig:ladder}" not in expt,
       "the ladder figure is still in experiments.tex as well")
    lad = re.search(r"newlabel\{fig:ladder\}\{\{[^}]*\}\{(\d+)\}", aux)
    crit = re.search(r"newlabel\{tab:criteria\}\{\{[^}]*\}\{(\d+)\}", aux)
    # ROUND-31 SUBSTITUTION (the user's "demote tab:criteria" decision): the
    # object that now sits beside the ladder is tab:claim_ledger, not
    # tab:criteria -- which is the whole point of the demotion, so the
    # adjacency requirement MOVES to the ledger rather than being dropped.
    # tab:criteria must be in the appendix, and the operational column it used
    # to carry is folded into fig:ladder's "Reached by" cells (pinned in
    # group 31), so the auditor-executable protocol stays in the main text.
    ledg = re.search(r"newlabel\{tab:claim_ledger\}\{\{[^}]*\}\{(\d+)\}", aux)
    ck(lad and ledg and abs(int(lad.group(1)) - int(ledg.group(1))) <= 1,
       "the ladder and tab:claim_ledger are no longer on the same or adjacent "
       "pages")
    ck(crit and int(crit.group(1)) > 9,
       "tab:criteria came back into the main text, which re-spends the rulers "
       "round 31 used to land tab:claim_ledger on p5")
    ck(lad and int(lad.group(1)) < 8,
       "the ladder did not move earlier than its round-21 page (p8)")
    # its two local references sit in the file that now draws it
    ck(meth.count("\\ref{fig:ladder}") == 2,
       f"methodology.tex holds {meth.count(chr(92) + 'ref{fig:ladder}')} refs to "
       f"the ladder, expected 2")
    ck(expt.count("\\ref{fig:ladder}") == 0,
       "experiments.tex still references the ladder from a later page")
    # adjacent captions must not open with the same phrase
    ck("\\textbf{The audit protocol as an evidence ladder, and where this paper "
       "stops.}" in meth,
       "the ladder's caption does not own the evidence-ladder framing")
    # ROUND-31 ROUTING: read from appendix.tex, tab:criteria's new home. The
    # check is a PRESENT check despite its message -- the caption must still
    # open on its own phrase rather than the ladder's.
    ck("\\textbf{The audit protocol, criterion by criterion} (drawn as "
       "Figure~\\ref{fig:ladder})" in app,
       "tab:criteria's caption no longer opens with its own phrase")
    ck(meth.count("as an evidence ladder") == 1,
       f"'as an evidence ladder' appears {meth.count('as an evidence ladder')} "
       f"times in the two adjacent captions, expected 1")
    ck("\\textbf{Table~\\ref{tab:criteria} drawn as a ladder" not in meth,
       "the figure caption still describes the table it now sits beside")
    # tab:external_audit slipped to p8. It used to be an unreferenced float --
    # three \refs in the appendix, none in the main text -- so it now has one, at
    # the claim it tabulates, and that reference must land on its own page or later
    ck(main_txt.count("\\ref{tab:external_audit}") >= 1,
       "tab:external_audit is an unreferenced main-text float again")
    # ROUND-26 SUBSTITUTION (funding rung 5 / §10): the four-requirement
    # enumeration ("independent grading, matched realizations, ... never co-occur in
