    ck(len(pre) == 16, f"27j: {len(pre)} pre-registrations, expected 16 "
                       f"(12 frozen + EXP-AD + EXP-AE + EXP-AF + EXP-FS)")
    for f in ["PREREG_EXP_AD.md", "PREREG_EXP_AE.md", "PREREG_EXP_AF.md",
              "PREREG_EXP_FS.md"]:
        ck(f in pre, f"27j: docs/{f} is missing")

    # The disk count and the main text's number word are DELIBERATELY allowed to
    # differ by one between the freeze of EXP-FS and its integration (B4): a
    # pre-registration exists the moment it is frozen, but §3.1 counts only the
    # analyses the main text actually reports. Rather than let that slack hide a
    # half-finished transaction, the two are tied together by the state of the
    # frontier appendix. This is the five-site consistency guard: the likeliest
    # defect in round 30 is promoting the frontier material while leaving one of
    # its dependent sites stale, and this check fires on exactly that.
    # Re-stated locally: the round-26 originals are function-local to the vintage
    # gate, and reaching across scopes to borrow them is how a check silently
    # becomes a NameError that never runs.
    NOT_EST_30 = ("We do not establish that the collapse reproduces on "
                  "current-generation models")
    NO_RECENCY_30 = "claim below is a scaling, recency or effect-magnitude claim"

    # ROUND-30 CORRECTION TO THIS TRIGGER, and the reason is worth stating because
    # the old form would have failed on the very transaction it exists to police.
    # Keying on the bare phrase "Not Load-Bearing for Any Claim" anywhere in
    # appendix.tex was wrong: THREE unrelated sections (white-box probing EXP-P,
    # sycophancy transfer, the Qwen~2.5~14B persona spot-check) carry that title
    # legitimately and B4 does not touch them, so the phrase never leaves the file.
    # The trigger would therefore still read False after B4 completed, take the
    # else branch, and demand "fifteen" from a §3.1 that by then says "sixteen".
    # It now keys on the frontier section's OWN old title, which is exactly what
    # B4 rewrites and nothing else does.
    # (FS_OLD_TITLE is module scope: check 15g needs the same trigger.)
    UNRELATED_EXPLORATORY = [
        "\\section{White-Box Probing Results (Exploratory: Not Load-Bearing "
        "for Any Claim)}",
        "\\section{Sycophancy Transfer: Mechanistic Detail (Exploratory: Not "
        "Load-Bearing for Any Claim)}",
        "\\section{Qwen~2.5~14B Persona Qualitative Spot-Check (Exploratory: "
        "Not Load-Bearing for Any Claim)}",
    ]
    # Inverse check, run in BOTH branches: B4 must not over-apply. Stripping the
    # exploratory marking from sections that stay exploratory is the mirror image
    # of the half-application defect, and just as much of an overclaim.
    for _s in UNRELATED_EXPLORATORY:
        ck(_s in app,
           "30-transaction: an UNRELATED exploratory section lost its 'Not "
           "Load-Bearing for Any Claim' marking, so B4 over-applied: "
           f"{_s[:70]!r}")

    fs_load_bearing = FS_OLD_TITLE not in app
    if fs_load_bearing:
        ck("sixteen pre-registered analyses" in expt,
           "27j/30-transaction: the frontier appendix no longer says 'Not "
           "Load-Bearing for Any Claim', so EXP-FS is load-bearing and §3.1 must "
           "count SIXTEEN pre-registered analyses -- it still says fifteen")
        ck(NOT_EST_30 not in app,
           "27j/30-transaction: EXP-FS is load-bearing but app:vintage still "
           "disclaims establishing the collapse on current-generation models")
        ck(NO_RECENCY_30 not in expt,
           "27j/30-transaction: EXP-FS is load-bearing but §3.1 still asserts "
           "'no claim below is a scaling, recency or effect-magnitude claim'")

        # ---- ROUND-30 DEPARTURE FROM THE PLAN, asserted as an INVERSE check.
        # The plan said to weaken the reader's-guide invariant "No claim in
        # §3.2--§3.5 depends on anything in bucket~4". B4 instead MOVES the two
        # frontier sections out of bucket 4 into bucket 2, so the invariant stays
        # literally true and must SURVIVE rather than disappear.
        #
        # The check it replaces was a FALSE PASS and had been since round 27: it
        # tested for the literal "No claim in §3.2--§3.5 depends on anything in
        # bucket 4", but the source writes the range as
        # "§\ref{sec:r1_faithful}--§\ref{sec:external_audit}" and breaks the line
        # before "anything", so BOTH disjuncts were vacuously satisfied and the
        # check could never fire in either direction. Matched against the real
        # string now.
        ck("anything in bucket~4" in app,
           "30-transaction: the reader's-guide bucket-4 invariant was deleted. B4 "
           "keeps it TRUE by moving the frontier sections into bucket 2 instead, "
           "so deleting it discards a still-valid reader guarantee")
        ck("Frontier-scale preliminaries (\\ref{app:frontier_preliminary})"
           not in app,
           "30-transaction: bucket 4 still lists the frontier sections while the "
           "reader's guide promises nothing in §3.2--§3.5 depends on bucket 4, and "
           "§3.1/§3.4 now report EXP-FS -- the two are contradictory")
        ck("pre-registered frontier-scale panel over" in app,
           "30-transaction: the frontier sections left bucket 4 but never arrived "
           "in bucket 2, so the roadmap now omits load-bearing evidence entirely")

        # ---- the remaining B4 sites. A half-applied five-site transaction is this
        # round's named largest failure mode, so every site B4 touches is pinned.
        abst30, disc30 = read("abstract.tex"), read("discussion.tex")
        ck("\\textbf{Scope: English, instructed-roleplay evaluations, "
           "open-weight models 3B--70B.}" not in abst30,
           "30-transaction: EXP-FS is load-bearing but the abstract still scopes "
           "the paper to open-weight models 3B--70B")
        ck("English-language instructed roleplay on instruction-tuned "
           "open-weight models, 3B--70B" not in disc30,
           "30-transaction: EXP-FS is load-bearing but §4's scope statement still "
           "says instruction-tuned open-weight models, 3B--70B")
        ck("frontier-scale targets from" in abst30,
           "30-transaction: the abstract's scope line was widened but does not "
           "name the frontier panel")
        ck("frontier targets}" in disc30,
           "30-transaction: §4's scope line was widened but does not name the "
           "frontier targets")

        # The main text must REPORT the panel, not merely stop disclaiming it.
        # Dropping a disclaimer without adding the evidence is the failure mode
        # that would leave the paper claiming more than it shows.
        # ROUND-30 CORRECTION to this check's own expected string, not to the
        # paper. It was drafted as "\textbf{EXP-FS} adds", which check 29n
        # FORBIDS: no main-text sentence may open on a bare EXP- tag. The applied
