        ck("frontier-scale targets from" in expt,
           "30-transaction: §3.1 introduces the panel without naming its roster "
           "size, so the reader cannot tell what the recency claim rests on")
        ck("Frontier scale: rule" in expt,
           "30-transaction: §3.4 does not report the panel's two outcomes, so the "
           "retired disclaimers are unbacked in the main text")
