        ck(sorted(c4["explained_targets"]) == ["llama3.1:8b", "qwen2.5:7b"],
           f"27l: EXP-C4's explained set is {c4['explained_targets']}, not the "
           f"two the appendix reports")
        ck(c4["per_target"]["llama3.1:8b"]["verdict"] == "EXPLAINED_BY_COVARIATES",
           "27l: the withdrawn target's verdict is no longer EXPLAINED_BY_"
           "COVARIATES")
        # H-AE2 fails on every published positive: the paper must not read the
