    # check exists to defend is unchanged -- those three files and nothing else
    # are the round's code-side deliverable -- so it now asserts they are
    # TRACKED and that the tree is otherwise clean, which is strictly stronger
    # than the pre-commit form (that one passed with the files uncommitted).
    AF_FILES = ["adaptive_lie_detector/data/results/eccp_decidability.json",
                "adaptive_lie_detector/docs/PREREG_EXP_AF.md",
                "adaptive_lie_detector/experiments/analyze_eccp_decidability.py"]
    st = subprocess.run(["git", "status", "--porcelain"], capture_output=True,
                        text=True, cwd=REPO2).stdout.strip()
    # ROUND-30 SUBSTITUTION: EXP-FS's runner writes a *_checkpoint.json per cell so
    # a throttled run can resume without losing trials. Those are regenerable
    # intermediates, not deliverables -- the deliverable is the timestamped result
    # file and its _latest.json copy, and both ARE required to be tracked below.
    # Only the checkpoints are exempted, and only by exact name shape, so a stray
    # untracked results file still fails this check.
    CKPT = re.compile(r"^\?\? adaptive_lie_detector/data/results/"
                      r"frontier_panel_[a-z0-9_]+_checkpoint\.json$")
    st_lines = [ln for ln in st.splitlines() if not CKPT.match(ln.strip())]
    st_filtered = "\n".join(st_lines).strip()
    ck(st_filtered == "",
       f"28o: the code repo's working tree is not clean (run checkpoints "
       f"excluded): {st_filtered!r}")

    # ROUND-30 ADDITION: the EXP-FS integrity ordering, asserted from the commit
    # graph rather than from the letter's word. The pre-registration must be
    # committed strictly BEFORE the earliest result file in the panel exists.
    # This is the check the round-29 suite structurally lacked: 1373 checks and
    # not one of them compared a paper number, or a design freeze, to data.
    fs_prereg = os.path.join(REPO2, "docs", "PREREG_EXP_FS.md")
    if os.path.exists(fs_prereg):
        t_pre = subprocess.run(
            ["git", "log", "--diff-filter=A", "--format=%ct", "--",
             "docs/PREREG_EXP_FS.md"],
            capture_output=True, text=True, cwd=REPO2).stdout.split()
        ck(bool(t_pre), "30fs: PREREG_EXP_FS.md exists on disk but has no add "
                        "commit -- an unversioned pre-registration is not one")
        if t_pre:
            freeze = int(t_pre[-1])
            cells = glob.glob(os.path.join(
                REPO2, "data", "results", "frontier_panel_*_20*.json"))
            for c in cells:
                ck(os.path.getmtime(c) > freeze,
                   f"30fs: {os.path.basename(c)} predates the EXP-FS freeze -- "
                   f"the panel's design was not frozen before this cell ran")
    # porcelain and ls-files both speak repo-root-relative paths, and REPO2 is
    # one level BELOW that root, so resolve the root rather than joining onto
    # REPO2 -- doing the latter looks for adaptive_lie_detector twice over.
    root2 = subprocess.run(["git", "rev-parse", "--show-toplevel"],
                           capture_output=True, text=True,
                           cwd=REPO2).stdout.strip()
    ck(os.path.basename(root2) == "code",
       f"28o: the nested repo's root is {root2!r}, not code/")
    tracked = subprocess.run(["git", "ls-files"] + AF_FILES, capture_output=True,
                             text=True, cwd=root2).stdout.split()
    ck(sorted(tracked) == AF_FILES,
       f"28o: EXP-AF's files are not all tracked; git ls-files gives {tracked}")
    for f in AF_FILES:
        ck(os.path.exists(os.path.join(root2, f)),
           f"28o: {f} is tracked but missing from the working tree")
    for stray in ["main.tex", "main.aux", "main.fls", "main.fdb_latexmk",
                  "main.log", "main.pdf"]:
        ck(not os.path.exists(os.path.join(REPO2, stray)),
           f"28o: {stray} drifted into the code repo from a stray cwd")

    # 28p. the plan's check 5 -- the eleventh float pin, plus page pins for the
    # two round-27 appendix tables that were previously only checked for
    # existence. EXP-AF's section is inserted upstream of all three, so these
    # numbers ARE the round-28 measurement, not round 27's (p63/p65 -> p66/p68).
    # ROUND-29 SUBSTITUTION (B3): tab:roadmap is inserted into appendix.tex
    # upstream of tab:experiment_summary, so it repages p23 -> p24. Its NUMBER is
    # unchanged at 8 because the roadmap takes number 4, ahead of it.
    # ROUND-30 SUBSTITUTION (B4): tab:frontier_panel is a NEW appendix float at
    # 8/p23, upstream of all three of these -- so each takes the next number and
    # the next page (8/p24 -> 9/p25, 48/p66 -> 49/p67, 49/p68 -> 50/p69). This is
    # the deliberate renumbering B4 was expected to cause, not drift:
    # tab:eccp_decidability at 6/p19 is upstream of the new table and is pinned
    # UNMOVED here as the control that proves the shift is local to p23 onward.
    # ROUND-31 SUBSTITUTION: tab:criteria became appendix float 5/p16, upstream
    # of all five of these, so each takes the next NUMBER at an UNCHANGED PAGE
    # (6/p19 -> 7/p19, 8/p23 -> 9/p23, 9/p25 -> 10/p25, 49/p67 -> 50/p67,
    # 50/p69 -> 51/p69). Pages holding while numbers shift is the signature of
    # a pure renumbering: the demoted table landed inside Appendix A's existing
    # float queue without displacing any page of appendix body text.
    # ROUND-34 SUBSTITUTION: A1/A2 deleted appendix PROSE, never a float, so
    # every NUMBER below is unchanged and only pages move -- the signature of a
    # pure repagination, and the control that proves no table was dropped to buy
    # length. p19 -> p20 for tab:eccp_decidability (its Appendix-A neighbours
    # tab:roadmap 4/p15, tab:criteria 5/p16 and tab:appendix_roadmap 3/p14 are
    # unchanged because A4 ADDED the signpost paragraph upstream of them, which
    # offsets the cuts exactly there); tab:frontier_panel 9/p23 and
    # tab:experiment_summary 10/p25 unchanged; and the two late floats move
    # BACKWARD by one page (p68 -> p67, p70 -> p69), which is the deletion
    # showing up where the deletions are.
    for lab, num, page in [("tab:eccp_decidability", "7", "20"),
                           ("tab:frontier_panel", "9", "23"),
                           ("tab:experiment_summary", "10", "25"),
                           # ROUND-32 SUBSTITUTION: A4's tab:inference_ladder
                           # is a new appendix float at p41, so both of these
                           # shift by exactly one number and one page. Updated
                           # rather than relaxed: a second shift still fires.
                           ("tab:dimension_transfer", "51", "67"),
                           ("tab:covariate_audit", "52", "69")]:
        m = re.search(r"newlabel\{" + re.escape(lab) + r"\}\{\{([^}]*)\}\{(\d+)\}",
                      aux)
        ck(m is not None, f"28p: float {lab} has no newlabel")
        if m:
            ck(m.group(1) == num and m.group(2) == page,
               f"28p: float {lab} moved: now {m.group(1)} on p{m.group(2)}, "
               f"expected {num} on p{page}")
            ck(int(m.group(2)) > 9,
               f"28p: {lab} landed in the main text, on p{m.group(2)}")

    # ==== GROUP 29 -- the clarity round =====================================
    # Round 29 is a presentation round: one spine (Q1/Q2/Q3), three named
    # claims, five criteria in three lettered groups, descriptive experiment
    # names.  The reviewer's binding constraint was "less terminology, not less
    # precision", so this group is deliberately half present-checks and half
    # INVERSE checks (29r--29y) asserting that the simplification did not drop a
    # qualification.
    disc29 = read("discussion.tex")
    main29 = absr + intro + meth + expt + disc29 + concl

    # ---- step 6: asserted present ----------------------------------------

    # 29a. the Q1/Q2/Q3 spine reaches the section headings.  Six subsections
    # carry a Q-tag; "Experimental Setup" correctly does not.
    heads29 = re.findall(r"\\subsection\{([^}]*)\}", meth + expt)
    # ROUND-33 SUBSTITUTION (A1, their §25C + clarity item #3): §3's four
    # subsections now also name the rung each one moves the evidence to, so the
    # table of contents reads as the ladder. §2's two headings and "Experimental
    # Setup" are unchanged -- §2 states the protocol rather than climbing it.
    ck(heads29 == [
        "Q2: Why the Instructed Contrast Cannot Be Attributed",
        "Q2/Q3: An Audit Protocol for Behavioral Deception Benchmarks",
        "Experimental Setup",
        "Q1, then Q2, Rung 1 to 2: The Prior Detector Collapses Under "
        "Equalization (EXP-R1, EXP-R1b/R1c)",
        "Q2, Rung 2 to 3: What Survives Is Reproducible from Surface Behavior "
        "and Model Knowledge",
        "Q2, Rung 2 to 3 Again: A Third Detector Paradigm, and Supporting "
        "Analyses",
        "Q3, Rung 3 to 4: Criterion 4 on Public Corpora, and on Materials Built "
        "for It (EXP-XA/XJ/XL, EXP-C4)",
    ], f"29a: the Q-tagged subsection headings changed: {heads29}")
    ck(len([h for h in heads29 if re.match(r"Q[123]", h)]) == 6,
       "29a: six subsection headings must carry a Q-tag")

    # 29b. the spine reaches tab:criteria too, so the criteria are read as
    # answers to the questions rather than as a free-standing list of five.
    # ROUND-31 ROUTING: tab:criteria's caption is now in appendix.tex.
    ck("\\textbf{Group~A answers Q2; group~B answers Q3.}" in app,
       "29b: tab:criteria's caption lost the group -> question mapping")

    # 29c. their explicitly requested master sentence, and it must be the LAST
    # thing in the introduction -- a takeaway the reader leaves the section with.
    master29 = ("\\noindent\\textbf{In one sentence}: \\textbf{instructed-lie "
                "benchmarks answer Q1 and cannot answer Q2, because the "
                "instruction that creates the deception also creates the "
                "behavior a detector reads; answering Q2 requires materials in "
                "which deception varies while the elicitation is held "
                "byte-identical, and when we build them, prior work's own "
                "battery separates deception on one of five targets.}")
    ck(master29 in intro, "29c: the introduction's master sentence is gone or "
                          "reworded")
    _tail29 = [p for p in intro.strip().split("\n") if p.strip()]
    ck(_tail29 and _tail29[-1].startswith("\\noindent\\textbf{In one sentence}"),
       "29c: the master sentence is no longer the last line of the "
       "introduction")

    # 29d. three NAMED claims, with the inner (1)--(4) numbering intact --
    # main.tex's ethics statement cites claim~(4) and the conclusion carries a
    # five-item establishes ledger, so the numbers cannot be collapsed.
    for nm in ["\\textsc{i.~identification}",
               "\\textsc{ii.~what a valid test requires}",
               "\\textsc{iii.~empirical diagnosis}"]:
        ck(nm in intro, f"29d: claim name {nm} is missing")
    ck("Contribution: three claims" in intro,
       "29d: the contribution paragraph no longer bills three claims")
    for n in ["\\textbf{(1)~Framework.}", "\\textbf{(2)~Protocol",
              "\\textbf{(3)~Demonstration", "\\textbf{(4)~A construct-valid"]:
        ck(n in intro, f"29d: inner claim number {n} was lost in the renaming")

    # 29e. criterion 4 made VISUALLY distinct (their highest-rated structural
    # item after the abstract): A/B/C headers, and a filled marker on B against
    # hollow markers on A and C.
    for hdr in ["$\\square$~\\textbf{A. Confound diagnostics (1, 2, 3)}",
                "$\\blacksquare$~\\textbf{B. Construct-validity test (4)}",
                "$\\square$~\\textbf{C. Robustness (5)}"]:
        # ROUND-31 ROUTING: the A/B/C group headers travelled with the table.
        ck(hdr in app, f"29e: tab:criteria lost its group header {hdr!r}")
    ck(app.count("$\\blacksquare$") == 1 and app.count("$\\square$") == 2,
       "29e: the filled/hollow marker asymmetry that singles out group B is "
       f"broken: {app.count(chr(36) + chr(92) + 'blacksquare' + chr(36))} "
       "filled")
    ck(meth.count("$\\blacksquare$") == 0 and meth.count("$\\square$") == 0,
       "29e: the A/B/C markers are in methodology.tex as well as appendix.tex, "
       "so the demoted table was copied rather than moved")
    ck("\\paragraph{How the criteria divide: A (1,2,3) + B (4) + C (5).}"
       in meth, "29e: the 3+1+1 paragraph no longer uses the A/B/C names")
    for c in ["\\textbf{A}~diagnostics", "\\textbf{B}~construct validity",
              "\\textbf{C}~robustness"]:
        ck(c in expt, f"29e: tab:external_audit's caption lost {c!r}, so its "
                      "columns no longer carry tab:criteria's grouping")
    # their item 5's clause: WHY 4 is different in kind, not merely one of five
    ck("The division is \\emph{who can apply} a criterion" in meth
       and "A and C can be checked on someone else's benchmark, from the "
           "artifact as released; B requires building materials that no "
           "instructed design can supply" in meth,
       "29e: the who-can-apply clause distinguishing B from A and C is gone")

    # 29f. their item 11: the contrast belongs in the abstract's FIRST sentence.
    _ab1 = absr[:absr.index("We do not ask whether")]
    ck("as opposed to instruction-induced behavior" in _ab1,
       "29f: the abstract's opening no longer says deception AS OPPOSED TO "
       "instruction-induced behavior")

    # 29g. their required precision phrase on criterion 4, at both sites.
    for nm, txt in [("abstract", absr), ("experiments \u00a73.5", expt)]:
        ck("not an estimate of the prevalence or reliability of deception "
           "detection" in txt,
           f"29g: {nm} lost the criterion-4 purpose qualification")
    ck("criterion-4-valid materials can produce a deception-associated signal"
       in absr and "criterion-4-valid materials can produce a "
                   "deception-associated signal" in expt,
       "29g: the demonstration-not-estimate framing was reworded")

    # 29h. their required scoping: the verdict is about the audited releases.
    ck("no public release we audited supplies all five" in absr,
       "29h: the abstract's public-release verdict lost its audited scope")
    ck("no audited public set satisfies all five" in expt,
       "29h: \u00a73.5's Stated-exactly verdict lost its audited scope")
    ck("No audited public release supplies all five requirements" in meth,
       "29h: the methodology fbox's (d) lost its audited scope")

    # 29i. their item 8: the reader meets the limits on pp. 2--3, in plain
    # terms, not on p5 in notation.
    ck("\\paragraph{What we do not establish, in plain terms.}" in intro,
       "29i: the plain-terms limits paragraph left the introduction")
    _plain29 = intro[intro.index("\\paragraph{What we do not establish, in "
                                 "plain terms.}"):]
    _plain29 = _plain29[:_plain29.index("\\noindent\\textbf{In one sentence}")]
    for lim in ["That deception is undetectable",
                "published detectors encode only instruction-following",
                "equalization shows a deception signal to be \\emph{absent} "
                "rather than removed along with the confound",
                "the audited corpora contain no deception",
                "the signal we do find at fixed elicitation is deception "
                "rather than a correlate of it"]:
        ck(lim in _plain29,
           f"29i: the plain-terms limits paragraph lost {lim!r}")

    # 29j. the identification-vs-generalization contrast, and it must NOT be a
    # float -- a numbered table here would renumber every pin in group 28p.
    _ctr29 = intro[intro.index("\\begin{center}\\small"):]
    _ctr29 = _ctr29[:_ctr29.index("\\end{center}")]
    ck("\\textbf{Generalization} (concurrent work)" in _ctr29
       and "\\textbf{Identification} (this paper)" in _ctr29,
       "29j: the identification-vs-generalization contrast tabular is gone")
    for row in ["Does a detector fit in regime~A still work in regime~B?",
                "Does accuracy in regime~A measure deception \\emph{at all}?",
                "One intervention moves two candidate causes",
                "\\textbf{A different intervention}"]:
        ck(row in _ctr29, f"29j: the contrast tabular lost the row {row!r}")
    ck("\\begin{table}" not in _ctr29 and "\\caption" not in _ctr29
       and "\\label{tab:" not in _ctr29,
       "29j: the contrast tabular became a numbered float -- that renumbers "
       "every float pin in 28p and 13f")

    # 29k. their item 2: name the three objects that carry the argument, so
    # Figure 1 -> Figure 2 -> Table reads as a spine rather than as three
    # unrelated exhibits.
    # ROUND-31 SUBSTITUTION (their §17): three objects -> FOUR. tab:claim_ledger
    # is the object they asked for by name, so the spine sentence has to name it
    # or the reader meets the ledger without being told what it is for. The
    # other three names and their order are unchanged, and the check is still
    # exact-string rather than a count.
    ck("\\textbf{Four objects carry the argument}: Figure~\\ref{fig:dag} "
       "shows why instructed accuracy cannot attribute itself, "
       "Figure~\\ref{fig:ladder} how far the evidence reaches, "
       "\\textbf{Table~\\ref{tab:claim_ledger} every claim with its "
       "confirmatory experiment, primary metric, pre-registration and "
       "replication status}, and Table~\\ref{tab:external_audit} what the audit "
       "found in every setting." in intro,
       "29k: the spine sentence naming all four objects is gone or no longer "
       "names all four")

    # 29l. B3 demoted tab:roadmap, so the pointer is what keeps round 23's
    # question -> evidence -> result -> warrant mapping FINDABLE.  Deleting
    # this pointer re-opens a satisfied round-23 item.
    ck('\\textbf{The full mapping (question $\\to$ evidence $\\to$ result '
       "$\\to$ what it licenses, row by row, with pre-registration status "
       "marked) is Table~\\ref{tab:roadmap}, in the appendix's reader's "
       "guide}" in intro,
       "29l: the pointer to the demoted roadmap is gone -- round 23 asked for "
       "this mapping by name")
    for g in ["\\textbf{A.~Structural}", "\\textbf{B.~Empirical}",
              "\\textbf{C.~Attribution}"]:
        ck(g in intro, f"29l: the roadmap pointer lost its claim group {g}")
    ck("\\label{tab:roadmap}" in _appx_r29
       and "\\label{tab:roadmap}" not in intro,
       "29l: tab:roadmap is not where B3 put it (appendix, not introduction)")

    # ---- step 7: asserted absent -----------------------------------------

    # 29m. their item 4: early prose notation is E, D, C, S -- four symbols, not
    # six.  V is reintroduced only in the Proposition's own setup sentence, and
    # B not at all; fig:dag's V/B nodes are self-labelling and exempt (13f pins
    # that TikZ byte-identical).
    _s21 = meth[meth.index("\\subsection{Q2: Why"):
                meth.index("\\subsection{Q2/Q3:")]
    _early29 = _s21[:_s21.index("\\noindent In the statement below")]
    ck(sorted(set(re.findall(r"\$([EDCSVB])(?![a-zA-Z])", _early29)))
       == ["C", "D", "E", "S"],
       "29m: \u00a72.1's early prose notation is no longer exactly {E,D,C,S}: "
       + str(sorted(set(re.findall(r"\$([EDCSVB])(?![a-zA-Z])", _early29)))))
    ck(len(re.findall(r"\$B(?![a-zA-Z])", meth)) == 0,
       "29m: $B$ came back into methodology.tex")
    ck(len(re.findall(r"\$V(?![a-zA-Z])", _early29)) == 0,
       "29m: $V$ came back into \u00a72.1's prose ahead of the Proposition")
    ck("the claim's truth-value and the target's belief are all parents of $S$"
       in meth,
       "29m: B4's English-name rewrite of the V/B sentence was reverted")

    # 29n. their item 3, the strict form: an experiment ID may never be the
    # grammatical subject of a main-text sentence.  A bare EXP- token opening a
    # sentence or a paragraph is the failure mode they named.
    _bare29 = []
    for m in re.finditer(r"(?:^|\.\s+|\.\}\s+|\n\n)\\?(?:textbf\{)?(EXP-[A-Za-z0-9]+)",
                         main29):
        _bare29.append(m.group(1))
    ck(_bare29 == [],
       f"29n: an experiment ID opens a sentence as its subject: {_bare29}")

    # 29o. C1's defect, asserted absent for good.
    ck("four negatives" not in main29 and "four negatives" not in app,
       "29o: the four-vs-five negatives defect (C1) came back")

    # 29p. their framing: introduce the PROBLEM first, attach the formal name
    # later.  The abstract states it in words; the name lives in the
    # introduction, methodology and conclusion (28a).
    ck("Elicitation--Construct Confounding Principle" not in absr
       and "ECCP" not in absr,
       "29p: the ECCP name is back in the abstract -- they asked for the "
       "problem first and the name later")

    # 29q. their required scoping, as a negative: never generalize the verdict
    # past the releases actually audited.
    for bad in ["deception benchmarks generally", "all deception benchmarks",
                "no deception benchmark supplies", "deception benchmarks in "
                "general", "any deception benchmark supplies"]:
        ck(bad not in main29,
           f"29q: {bad!r} over-generalizes the audit verdict beyond the "
           "audited releases")

    # ---- step 8: INVERSE checks -- what must survive the simplification ---
    # The reviewer warned that this round's edits are exactly the ones that
    # quietly drop a qualification.  These assert the precision is still there.

    # 29r. the Proposition stays general over k mechanisms; deception is one
    # instantiation, not the statement.
    ck("Let $M_1,\\dots,M_k$ be latent mechanisms that $\\mathrm{do}(E)$ "
       "shifts" in meth
       and "for any causal arrangement among the $M_i$ consistent with all of "
           "them being descendants of $E$" in meth
       and "With $(M_1,M_2)=(D,C)$" in meth,
       "29r: the Proposition lost its general statement over $M_1,\\dots,M_k$")

    # 29s. the two-senses-of-necessary split, in BOTH places it is made.
    ck("\\textbf{Two senses of ``necessary'', kept apart}" in meth
       and "(iii)~is how an auditor \\emph{checks}" in meth
       and "(v)~rules out definitional circularity" in meth,
       "29s: methodology lost the (iii)/(v) two-senses split")
    ck("necessary for identification" in app
       and "necessary for this audit to be operational" in meth,
       "29s: the identification-vs-operational distinction was flattened")

    # 29t. 28a's ECCP siting, restated as an inverse check now that 29p bars
    # the abstract: the name must survive in all three remaining homes.
    for nm, txt in [("methodology", meth), ("introduction", intro),
                    ("conclusion", concl)]:
        ck("Elicitation--Construct Confounding Principle" in txt,
           f"29t: the ECCP name left {nm} -- 29p removed it from the abstract, "
           "so all three of these are load-bearing")

    # 29u. all five Does-not-establish items, at the fbox that still owns them.
    _fbox29 = meth[meth.index("\\textbf{Does not establish.}"):]
    _fbox29 = _fbox29[:_fbox29.index("\\textbf{Unresolved.}")]
    for i, frag in [(1, "Anything against Q1, or that published detectors "
                        "measure only instruction-following"),
                    (2, "That equalization establishes the \\emph{absence} of "
                        "a signal"),
                    (3, "That the residual is entirely lexical"),
                    (4, "That the audited rollout sets contain no deception"),
                    (5, "That the fixed-elicitation signal is deception "
                        "\\emph{rather than} a correlate of it")]:
        ck(frag in _fbox29,
           f"29u: Does-not-establish item ({i}) was lost or reworded")
    ck(len(re.findall(r"\\textbf\{\((\d)\)\}", _fbox29)) == 5,
       "29u: the Does-not-establish list no longer has exactly five numbered "
       "items")

    # 29v. round 28's T5: EXP-AD keeps its three-line narrative.  It was NOT a
    # funding source this round.
    _ad29 = expt[expt.index("The benchmark can manufacture its own apparent"):]
    for frag in ["would you point it out without being asked?",
                 "At byte-identical elicitation the \\emph{same} probe is "
                 "\\textbf{inert}",
                 "would you stake your reputation on the accuracy of what you "
                 "just said?",
                 "So benchmark design can determine which behavioral signal "
                 "appears to constitute deception detection.",
                 "The two regimes use \\emph{different claim sets}"]:
        ck(frag in _ad29, f"29v: EXP-AD's narrative lost {frag!r}")

    # 29w. B2 consolidated caveats -- these three must survive consolidation.
    ck("because the contrast reuses \\emph{prior work's own} battery, a null "
       "is partly about \\textbf{that instrument's portability}" in expt,
       "29w: the same-battery portability caveat was consolidated away")
    ck("deception-\\emph{associated}, not $\\tau_D$" in expt,
       "29w: the deception-associated-not-causal qualification was lost from "
       "\u00a73.5")
    ck("The two regimes use \\emph{different claim sets}, so this is transfer "
       "\\emph{between designs}, not a causal effect of elicitation" in expt,
       "29w: EXP-AD's different-claim-sets limitation was consolidated away")

    # 29x. the decidable-precondition / measured-magnitude split, both sites.
    ck("\\textbf{Outside deception the precondition is thus decidable and "
       "decided; the magnitude is measured only for deception}" in meth,
       "29x: methodology lost the decidable/measured split")
    ck("\\textbf{Its precondition is decidable outside deception and we "
       "decide it}" in concl
       and "\\textbf{while its magnitude we measure only for behavioral "
           "deception detection}" in concl,
       "29x: the conclusion lost the decidable/measured split")

    # 29y. the structured caution boxes.  MEASURED, not assumed: the main text
    # carries THREE \fbox{\parbox} boxes -- the Q1/Q2/Q3 box and the
    # would-settle-it design box in the introduction, and the
    # proven/shown/unresolved box in methodology.  (The round-29 plan said
    # "five caution boxes"; that figure was wrong, and five is the count of the
    # Does-not-establish ITEMS inside the third box, checked at 29u.)
    ck(main29.count("\\fbox{\\parbox") == 3,
       f"29y: the main text has {main29.count(chr(92) + 'fbox' + chr(92) + '{' + chr(92) + 'parbox')} "
       "structured caution boxes, not 3 -- every previous reviewer named these "
       "a strength, so none may be cut")
    ck(intro.count("\\fbox{\\parbox") == 2
       and meth.count("\\fbox{\\parbox") == 1,
       "29y: a caution box moved between sections")
    for frag in ["\\textbf{Three questions, kept apart.}",
                 "\\textbf{The design that would settle the attribution "
                 'question, stated in full and then run.}',
                 "\\textbf{What is proven, what is shown at fixed "
                 "elicitation, and what is unresolved.}"]:
        ck(frag in main29, f"29y: caution box {frag!r} lost its heading")

    # ---- step 9: counts ---------------------------------------------------

    # 29z. the abstract's shape.  MEASURED AND PINNED AT THE ACHIEVED FIGURE,
    # not at the plan's target of ~250 words, and the gap is deliberate:
    # ten of the abstract's thirteen sentences are pinned verbatim by earlier
    # rounds' must-fixes (R2's pathway non-separability and tau_D demotion, T9's
    # thesis sentence, "The audit has five parts", the 97.0->43.3 / 69--80%
    # results, the standing 1-of-5 chain, round 27's T7 fixed-elicitation
    # clause -- which a PRIOR reviewer asked to have promoted INTO the abstract,
    # checked at 27g -- the rung-4 implication, the Scope line and 27h's opening
    # prefix).  Reaching 250 would mean reversing those.  511 -> 388 words is
    # what their shape allows; the letter states this.
    _abody = absr[absr.index("\\begin{abstract}") + 16:
                  absr.index("\\end{abstract}")]
    _aplain = re.sub(r"\\[a-zA-Z]+\*?|[{}$~\\]", " ", _abody)
    _awords = [t for t in _aplain.split() if re.search(r"[A-Za-z0-9]", t)]
    # ROUND-30 SUBSTITUTION: 388 -> 401. B4 must widen the Scope line, or the
    # abstract scopes the paper to "open-weight models 3B--70B" while the paper
    # reports a seven-organization frontier panel -- a contradiction, not a length
    # saving. The widening is +13 words and the round-29 "< 400" ceiling was a
    # round-boundary artifact, so it is REPLACED by a strictly stronger ratchet
    # rather than nudged: the abstract minus its Scope sentence must still be 381
    # words, exactly as at round 29 (381 + 7 = 388 then, 381 + 20 = 401 now). That
    # makes it impossible for any OTHER sentence to grow, which is what the 400
    # was standing in for, and it localises the entire increase to the one
    # sentence the round's evidence forced. The Scope line is the abstract's last
    # sentence, so the split point is exact.
    # ROUND-31 SUBSTITUTION (A4, their §21.4): 401 -> 403. The abstract said the
    # benchmark identifies "the identified $\tau_E$"; their objection is that
    # accuracy is not a monotone estimator of tau_E, so the phrase claims more
    # than holds. The replacement names the separation instead of the estimand
    # and costs two words. Updated, not relaxed -- a third word still fires.
    # ROUND-36 SUBSTITUTION (em-dash conversion): 403 -> 407. Every prose `---` in
    # the paper became ordinary punctuation; the abstract has four of them, and
    # `X---Y` is ONE whitespace-delimited token where `X, Y` is two. No prose was
    # added. Updated rather than relaxed, and the ratchet is RESTORED at full
    # strength below by re-counting the un-converted abstract, which must still be
    # exactly the 403 words round 31 pinned.
    ck(len(_awords) == 407,
       f"29z: the abstract is {len(_awords)} words, pinned at 407 (403 before "
       "round 36's em-dash conversion, 401 before round 31, 388 before round 30, "
       "511 before round 29). If this changed deliberately, re-read 27g and R2 "
       "first")
    _ascope_at = _abody.index("\\textbf{Scope:")
    _abody_words = [t for t in re.sub(r"\\[a-zA-Z]+\*?|[{}$~\\]", " ",
                                      _abody[:_ascope_at]).split()
                    if re.search(r"[A-Za-z0-9]", t)]
    # ROUND-31 SUBSTITUTION: 381 -> 383, the same two words as above. A4's edit
    # is in the BODY, not the Scope sentence, so both halves of the ratchet move
    # by two and the Scope sentence is pinned unchanged at 20 words by the
    # difference. No other sentence can grow without firing one of the two.
    # ROUND-36 SUBSTITUTION: 383 -> 387, the same four punctuation artifacts as
    # above. All four are in the BODY, so the Scope sentence is still pinned at 20
    # words by the difference check that follows.
    ck(len(_abody_words) == 387,
       f"29z: the abstract's non-Scope body is {len(_abody_words)} words, pinned "
       "at 387 (383 before round 36's em-dash conversion) -- only A4's tau_E "
       "rewording and round 36's repunctuation may move it")
    ck(len(_awords) - len(_abody_words) == 20,
       f"29z: the Scope sentence is {len(_awords) - len(_abody_words)} words, "
       "pinned at 20 -- round 31 changed the body, not the Scope line")
    # ROUND-36: the ratchet at FULL pre-conversion strength. Inverting round 36 must
    # give back exactly the 403/383 words round 31 pinned -- which proves the four
    # extra tokens are punctuation artifacts and that NO prose entered the abstract,
    # the property this ratchet exists to hold. Any real word added to the abstract
    # fires here even though the live counts moved.
    _abs36 = UNCONVERT(absr, "abstract")
    _body36 = _abs36[_abs36.index("\\begin{abstract}") + 16:
                     _abs36.index("\\end{abstract}")]

    def _w36(_s):
        return [_t for _t in re.sub(r"\\[a-zA-Z]+\*?|[{}$~\\]", " ", _s).split()
                if re.search(r"[A-Za-z0-9]", _t)]

    _n36 = len(_w36(_body36))
    _nb36 = len(_w36(_body36[:_body36.index("\\textbf{Scope:")]))
    ck(_n36 == 403,
       f"29z: un-converting round 36 leaves the abstract at {_n36} words, not "
       f"the 403 round 31 pinned -- so round 36 did more to the abstract than "
       f"repunctuate it")
    ck(_nb36 == 383,
       f"29z: un-converting round 36 leaves the non-Scope body at {_nb36} "
       f"words, not the 383 round 31 pinned")
    ck(_n36 - _nb36 == 20,
       f"29z: un-converted, the Scope sentence is {_n36 - _nb36} words, not 20")
    # and the conversion's size is itself pinned: -6 characters, four `---` sites
    # traded for four shorter marks.
    ck(len(absr) == 3248,
       f"abstract.tex is {len(absr)} chars, expected 3,248 (3,254 before round "
       f"36's four repunctuations)")
    ck(len(_awords) < 511,
       f"29z: the abstract grew back past its pre-round-29 length ({len(_awords)})")
    # their "only ~4 headline numbers": exactly four RESULT numbers survive.
    # The other three numerics are not results -- 3B--70B is the scope line's
    # model-size range and the two 4s are the criterion/rung labels.
    _anums = sorted(set(re.findall(r"\d+\.?\d*", _abody)))
    ck(_anums == ["3", "4", "43.3", "69", "70", "80", "97.0"],
       f"29z: the abstract's numeric tokens changed: {_anums}")
    ck(sorted({"97.0", "43.3", "69", "80"} & set(_anums)) ==
       ["43.3", "69", "80", "97.0"],
       "29z: one of the four headline result numbers left the abstract")
    ck(len(set(_anums) - {"3", "4", "70"}) == 4,
       f"29z: the abstract carries more than four result numbers: "
       f"{sorted(set(_anums) - {'3', '4', '70'})}")

    # 29aa. the standing 1-of-5 count, at all three sites round 25 requires.
    ck("the standing count is one of five" in absr,
       "29aa: the abstract lost the standing 1-of-5 count")
    ck("\\textbf{The standing count is one of five.}" in expt
       and "\\textbf{standing 1/5}" in expt,
       "29aa: \u00a73.5 lost the standing 1-of-5 count")
    ck("leaving one of five standing" in concl,
       "29aa: the conclusion lost the standing 1-of-5 count")

    # 29ab. the negatives count agrees between the list and every reference to
    # it -- this is exactly the disagreement C1 fixed.
    ck("the five negatives boxed in \u00a7\\ref{sec:eval_controls}" in concl,
       "29ab: the conclusion's pointer no longer says five negatives")
    # the plain-terms restatement is prose, so it is counted by its semicolons:
    # five limits separated by four semicolons, the last carrying "or".
    ck(_plain29.count(";") == 4 and "; or that" in _plain29,
       "29ab: the plain-terms paragraph no longer lists five limits")
    ck(_plain29.count(" that ") + _plain29.count("That ") >= 5,
       "29ab: the plain-terms paragraph restates fewer than five limits")

    # 29ac. the edit-shape pin, the round-29 analogue of 28n.  Round 29 is the
    # first round to ADD paragraphs rather than only rewrite them, which is why
    # gen_r29_edits.py had to learn anchor-widening.
    R29_SHAPE = {"abstract": 1, "introduction": 5, "methodology": 12,
                 "experiments": 9, "discussion": 1, "conclusion": 1}
    got29 = {}
    for e in R29_EDITS:
        got29[e[0]] = got29.get(e[0], 0) + 1
    ck({k: got29.get(k, 0) for k in R29_SHAPE} == R29_SHAPE,
       f"29ac: the round-29 edit shape is {got29}, expected {R29_SHAPE} -- an "
       "edit was added or removed without review")
    # 28n asserts discussion.tex has ZERO edits.  Round 29 touched it, so the
    # constraint is restated in its real form: it must not have been FUNDED
    # from.  Its word count rose, 179 -> 189.
    _dwords = len([t for t in re.sub(r"\\[a-zA-Z]+\*?|[{}$~\\]", " ", disc29)
                   .split() if re.search(r"[A-Za-z0-9]", t)])
    ck(_dwords >= 179,
       f"29ac: discussion.tex was funded from -- {_dwords} words, was 179 "
       "before this round and must not shrink")

    # 29ad. their 🔴1 applied to the demoted roadmap: it is the FULL
    # question -> evidence -> result -> warrant mapping, so every one of its six
    # question rows must carry the question it answers.  Three carried none
    # before this fix (the two Q2 rows and the factorial diagnostic).  The
    # roadmap is in the appendix, so these labels cost zero rulers.
    _rm29 = _appx_r29[_appx_r29.rindex(
        "\\begin{table}", 0, _appx_r29.index("\\label{tab:roadmap}")):]
    _rm29 = _rm29[:_rm29.index("\\end{table}")]
    for q in ["\\textbf{Q1. Does the paradigm produce high detector accuracy?}",
              "\\textbf{Q2. Does it survive removing the instruction "
              "asymmetry?}",
              "\\textbf{Q2. Is that accuracy reachable from surface "
              "behavior?}",
              "\\emph{Q2, diagnostic:} does the score move \\emph{inside} one "
              "deception label?",
              "\\textbf{Q2/Q3. Does $D$ vary at fixed $E$ in any audited "
              "corpus?}",
              "\\textbf{Q2/Q3. And in materials built to meet all five?}"]:
        ck(q in _rm29, f"29ad: the roadmap row {q[:52]!r} lost its Q-label")
    ck(len(re.findall(r"Q(?:1|2|2/Q3)[.,]", _rm29)) == 6,
       "29ad: the roadmap no longer has exactly six Q-labelled question rows: "
       + str(len(re.findall(r"Q(?:1|2|2/Q3)[.,]", _rm29))))

    # ======================================================================
    # GROUP 30 -- round 30: the mixture thesis sentence (A1), and the frontier
    # numbers pinned against committed data rather than against other prose.
    # ======================================================================
    intro30 = read("introduction.tex")

    # ---- 30a. the mixture sentence: present, in the introduction, and made of
    # numbers that already existed elsewhere in the paper. The last part is the
    # point -- this sentence was adopted as a SYNTHESIS, and if any of its
    # figures stops matching its source section the synthesis has drifted into a
    # new claim.
    ck("heterogeneous mixture" in intro30,
       "30a: the mixture thesis sentence is gone from introduction.tex")
    ck("What the accuracy aggregates" in intro30,
       "30a: the mixture sentence lost its lead-in label")
    for frag, why in [
        ("97.0\\% to 43.3\\%", "the equalization collapse"),
        ("69--80\\%", "the parameter-free rule's range"),
        ("70.0\\% KNOWN vs.\\ 57.6\\% UNKNOWN", "the knowledge-conflict stratum"),
        ("$p\\!=\\!0.0045$", "the knowledge-conflict p-value"),
        ("one of five targets", "the standing criterion-4 count"),
    ]:
        ck(frag in intro30, f"30a: the mixture sentence lost {why} ({frag!r})")

    # Every number in it must still exist in the section it summarizes, or the
    # synthesis has become an independent assertion.
    _e30 = read("experiments.tex")
    for frag, home in [("97.0", "experiments.tex"), ("43.3", "experiments.tex"),
                       ("69--80", "experiments.tex"), ("70.0", "experiments.tex"),
                       ("57.6", "experiments.tex"), ("0.0045", "experiments.tex")]:
        ck(frag in _e30,
           f"30a: the mixture sentence cites {frag} but {home} no longer "
           f"contains it -- the summary and its source have diverged")

    # The hedge is load-bearing: criterion 3's arm is stratified observational,
    # not randomised, and the reviewer's proposed wording asserted it flatly.
    ck("\\emph{consistent with} knowledge conflict" in intro30,
       "30a: the mixture sentence dropped the 'consistent with' hedge on "
       "knowledge conflict -- that arm is stratified observational, and the "
       "flat form overclaims it")
    ck("stratified observational" in intro30,
       "30a: the mixture sentence dropped its 'stratified observational' label")

    # ---- 30b. the retracted frontier values, absent everywhere. Nine numbers
    # were corrected in round 30; each reproduced from NO committed file under
    # any of the 9 pattern lists x 3 text channels x 3 thresholds in the code
    # repo. Pinned as forbidden strings so a later edit cannot reintroduce one.
    _all30 = "".join(read(f) for f in
                     ["abstract.tex", "introduction.tex", "methodology.tex",
                      "experiments.tex", "discussion.tex", "conclusion.tex",
                      "appendix.tex"])
    for bad, why in [
        ("Rule: 49.0\\%", "Sonnet's rule: a Maverick value under a non-canonical list"),
        ("Haiku pipeline: 83.0\\%", "Maverick's rule printed as Sonnet's pipeline"),
        ("in 5/50 lying, 6/50 truth", "Sonnet fire counts with no source"),
        ("in 44/50 lying, 17/50 truth", "Maverick fire counts with no source"),
        ("mean=1.84", "Llama 3.2 3B's RC mean attributed to Maverick"),
        ("mean=0.48", "Llama 3.2 3B's RC mean attributed to Maverick"),
        ("$-$16.2", "the inverted extractor gap, an estimator-mixing artifact"),
        ("inverted gap", "the inverted-gap framing"),
        ("\\emph{inverse} pattern", "the 'inverse pattern' claim: both cells fail alike"),
        ("suppress the refusal-marker channel",
         "the suppression mechanism, contradicted by 47/49 marker fires"),
    ]:
        ck(bad not in _all30, f"30b: retracted value/claim reintroduced -- {bad!r} ({why})")

    # ---- 30c. the corrected values, present and mutually consistent. The
    # defect these replace was a consistency failure BETWEEN sites, so the
    # corrected figures are pinned at every site that states them.
    app30 = read("appendix.tex")
    for frag, why in [
        ("Rule: 84.8\\%", "Sonnet's corrected rule accuracy"),
        ("47/49 lying, 13/50 truth", "Sonnet's corrected fire counts"),
        ("Haiku pipeline: 50.5\\% (degenerate", "Sonnet's corrected pipeline"),
        ("39/50 lying, 6/50 truth", "Maverick's corrected fire counts"),
        ("\\textit{92.9\\%} & \\textit{82.8\\%} & \\textit{78.8\\%} & \\textit{$+$12.1}",
         "the corrected Sonnet panel row"),
        ("extractor gap ($+$12.1\\,pp)", "the corrected gap heading"),
    ]:
        ck(frag in app30, f"30c: {why} is missing ({frag!r})")

    # 84.8 and 83.0 must agree wherever they appear -- the original defect was
    # the SAME cell carrying different numbers in the prose and in the table.
    ck(app30.count("84.8\\%") >= 2,
       "30c: Sonnet's corrected rule accuracy appears fewer than twice -- the "
       "prose and tab:frontier_comparison_app must both carry it")
    ck("\\textbf{83.0\\%} & 45.0\\%" in app30 or "83.0\\%} & 45.0\\%" in app30,
       "30c: tab:frontier_comparison_app's Maverick row lost the corrected "
       "83.0%/45.0% pairing")

    # ---- 30d. the disclosure paragraph. The correction is stated in the paper,
    # not only in the letter; if the paper's disclosure goes, the letter is
    # making a claim the manuscript does not support.
    ck("Earlier versions of this table reported" in app30,
       "30d: the appendix no longer discloses the corrected estimator error")
    ck("does not hold" in app30 and "84.8\\%" in app30,
       "30d: the appendix no longer retires the superseded suppression premise")

    # ---- 30e. the refusal-only column, deliberately NOT repinned. Recomputing
    # it with the documented method reproduces 0 of 9 rows, which indicts the
    # method rather than the paper. This check exists so a later round does not
    # "fix" nine correct numbers to match an unvalidated estimator.
    ck("68.7\\%" in app30,
       "30e: Sonnet's refusal-only 68.7% was changed. It was left alone in "
       "round 30 on purpose: the documented refusal-only method reproduces 0 of "
       "the column's 9 rows, so a mismatch there is evidence about the method, "
       "not about the paper. Do not repin this column without first reproducing "
       "the eight open-weight rows.")


    # ======================= GROUP 31 ======================================
    # Round 31 is the reviewer's own scoping: "I would not add more experiments
    # ... I would instead make five surgical changes." So this group pins FORM,
    # not new evidence -- and the inverse half (31h) pins that the two float
    # relocations did not quietly cost the paper anything a reviewer praised.
    intro31 = read("introduction.tex")
    meth31 = read("methodology.tex")
    expt31 = read("experiments.tex")
    app31 = read("appendix.tex")
    relw31 = read("related_work.tex")
    concl31 = read("conclusion.tex")
    absr31 = read("abstract.tex")

    # ---- 31a. A1, their §21.1: the contribution hierarchy, brutally explicit.
    # Three separately labelled items, each opening on its claim, in the order
    # the paragraph bills them.
    for _lab in ["\\textbf{Contribution~1 (\\textsc{identification}).}",
                 "\\noindent\\textbf{Contribution~2 "
                 "(\\textsc{what a valid test requires}).}",
                 "\\noindent\\textbf{Contribution~3 "
                 "(\\textsc{empirical diagnosis}).}"]:
        ck(_lab in intro31,
           f"31a: the contribution hierarchy lost its explicit label {_lab!r} -- "
           f"their §21.1 asked for 1/2/3 stated as such, not inferable")
    _c1 = intro31.index("\\textbf{Contribution~1")
    _c2 = intro31.index("\\textbf{Contribution~2")
    _c3 = intro31.index("\\textbf{Contribution~3")
    ck(_c1 < _c2 < _c3,
       "31a: the three contributions are no longer in billed order")
    # and each is its own paragraph, which is what "visually separated" means
    ck(intro31.count("\n\n\\noindent\\textbf{Contribution~1") == 1
       and intro31.count("\n\n\\noindent\\textbf{Contribution~2") == 1
       and intro31.count("\n\n\\noindent\\textbf{Contribution~3") == 1,
       "31a: a contribution is no longer its own paragraph, so the hierarchy "
       "reads as a run-on block again. All THREE break, not just 2 and 3: "
       "contribution 1 used to run on from the billing sentence, which made the "
       "visual hierarchy asymmetric in exactly the object their §21.1 asked to "
       "be brutally explicit")
    # the inner (1)--(4) numbering survives the restructuring: main.tex's ethics
    # statement cites claim~(4) and the conclusion carries a five-item ledger.
    for _n in ["\\textbf{(1)~Framework.}", "\\textbf{(2)~Protocol",
               "\\textbf{(3)~Demonstration", "\\textbf{(4)~A construct-valid"]:
        ck(_n in intro31,
           f"31a: inner claim number {_n} was lost in A1's restructuring")

    # ---- 31b. their §8/§20 novelty sentence, VERBATIM. They wrote it out, so a
    # paraphrase is a worse answer than a quotation; this is the only edit that
    # can move novelty 6, and it costs nothing.
    _nov = ("\\textbf{The novelty is not the observation that confounding "
            "exists; it is turning a previously implicit causal-validity "
            "requirement into an auditor-executable protocol and showing that "
            "existing behavioral deception benchmarks fail it in empirically "
            "distinct ways.}")
    ck(_nov in intro31,
       "31b: the reviewer's own novelty sentence is not in the introduction "
       "verbatim")
    ck(intro31.count(_nov) == 1,
       "31b: the novelty sentence appears more than once")

    # ---- 31c. A3, their §21.3: "independent" -> "mechanistically distinct" at
