    for _f, _t in [("abstract.tex", absr31), ("introduction.tex", intro31)]:
        ck("identified $\\tau_E$" not in _t and "identify $\\tau_E$" not in _t,
           f"31d: {_f} still says the benchmark identifies tau_E, which their "
           f"§21.4 objected to")

    # ---- 31e. A5, their §9: the ECCP is scoped AT ITS DEFINITION SITE, not two
