    ck("(EXP-AD)" in concl33,
       "33f: the conclusion's claim (5) lost its EXP-AD pointer along with the "
       "gloss, leaving the claim with no experiment attached")
    # this one was CUT, measured at 0 rulers, and RESTORED rather than spent for
