    _p10_33 = subprocess.run(["pdftotext", "-layout", "-f", "10", "-l", "10",
                              "main.pdf", "-"], capture_output=True,
                             text=True).stdout
    _flat9 = re.sub(r"\s+", " ", _p9_33)
